# KINGSMEN JARVIS STEP 01K2 - PARSE-SAFE EXACT LOCKED REFERENCE LAYOUT
# This writes the exact locked reference cockpit into the live Next.js Jarvis route.
# It does not search or score backups.
# It does not create a different visual concept.
# It backs up the current wrong screen first, writes the locked reference asset, writes TSX/CSS, then writes proof.

$ErrorActionPreference = "Stop"

function EnsureDir([string]$Path) {
  if (!(Test-Path $Path)) {
    New-Item -ItemType Directory -Force -Path $Path | Out-Null
  }
}

function WriteNoBom([string]$Path, [string]$Text) {
  EnsureDir (Split-Path -Parent $Path)
  $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Text, $utf8NoBom)
  Write-Host ("WROTE: " + $Path) -ForegroundColor Green
}

function WriteBytesFromB64([string]$Path, [string[]]$Chunks) {
  EnsureDir (Split-Path -Parent $Path)
  $b64 = ($Chunks -join "")
  [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($b64))
  Write-Host ("WROTE: " + $Path) -ForegroundColor Green
}

function Sha256File([string]$Path) {
  if (!(Test-Path $Path)) { return $null }
  $sha = [System.Security.Cryptography.SHA256]::Create()
  $bytes = [System.IO.File]::ReadAllBytes($Path)
  return [System.BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant()
}

Clear-Host
Write-Host "===============================================================" -ForegroundColor Cyan
Write-Host " KINGSMEN JARVIS STEP 01K2 - PARSE-SAFE EXACT LOCKED REFERENCE" -ForegroundColor Cyan
Write-Host "===============================================================" -ForegroundColor Cyan
Write-Host "Writes the locked reference cockpit. Backs up current wrong screen first." -ForegroundColor Yellow
Write-Host ""

$Repo = "C:\Kingsmen\kingsmen-platform"
if (!(Test-Path $Repo)) { throw "Repo not found: $Repo" }
if (!(Test-Path (Join-Path $Repo "apps\web"))) { throw "Web app not found: C:\Kingsmen\kingsmen-platform\apps\web" }

$HudRel = "apps\web\src\app\jarvis\JarvisHudClient.tsx"
$CssRel = "apps\web\src\app\jarvis\JarvisHud.module.css"
$AssetRel = "apps\web\public\jarvis\locked-reference.png"
$LiveHud = Join-Path $Repo $HudRel
$LiveCss = Join-Path $Repo $CssRel
$LiveAsset = Join-Path $Repo $AssetRel

$Stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupRoot = Join-Path $Repo ("backups\jarvis-step-01k2-before-parse-safe-exact-reference-" + $Stamp)
EnsureDir $BackupRoot

foreach ($rel in @($HudRel, $CssRel, $AssetRel)) {
  $src = Join-Path $Repo $rel
  if (Test-Path $src) {
    $dest = Join-Path $BackupRoot $rel
    EnsureDir (Split-Path -Parent $dest)
    Copy-Item $src $dest -Force
    Write-Host ("BACKED UP: " + $rel) -ForegroundColor DarkCyan
  }
}

