'@

WriteBytesFromB64 $LiveAsset $ImageChunks
WriteNoBom $LiveHud $Tsx
WriteNoBom $LiveCss $Css

$ExpectedImageSha = "99c79db673f8f8651bcabef4c3178a6f158ae10e41372ef24b7c21911e7268f7"
$ActualImageSha = Sha256File $LiveAsset
if ($ActualImageSha -ne $ExpectedImageSha) {
  throw "Locked reference image SHA mismatch. Expected $ExpectedImageSha but got $ActualImageSha"
}

$ManifestDir = Join-Path $Repo "manifests\jarvis"
$ReportsDir = Join-Path $Repo "reports\jarvis\steps"
$DocsDir = Join-Path $Repo "docs\jarvis"
$ToolsDir = Join-Path $Repo "tools\jarvis"
EnsureDir $ManifestDir
EnsureDir $ReportsDir
EnsureDir $DocsDir
EnsureDir $ToolsDir

$Now = (Get-Date).ToUniversalTime().ToString("o")
$LayoutLockPath = Join-Path $ManifestDir "jarvis-layout-lock.json"
$ProofPath = Join-Path $ReportsDir "STEP_01K2_PARSE_SAFE_EXACT_LOCKED_REFERENCE_LAYOUT_PROOF.json"
$ReportPath = Join-Path $ReportsDir "STEP_01K2_PARSE_SAFE_EXACT_LOCKED_REFERENCE_LAYOUT_REPORT.md"

$Lock = [ordered]@{
  lock_name = "jarvis-exact-locked-reference-layout"
  status = "LOCKED"
  locked_at = $Now
  source_reference = "PJ58C_EXACT_LOCKED_JARVIS_REFERENCE_PROOF.png"
  source_reference_sha256 = $ExpectedImageSha
  current_asset = $AssetRel
  safety_backup = $BackupRoot
  files_changed = @($HudRel, $CssRel, $AssetRel)
  rule = "Do not replace this visual with a scored backup. This is the locked reference cockpit."
  next = "Restart Next server, then open Jarvis app."
}
WriteNoBom $LayoutLockPath ($Lock | ConvertTo-Json -Depth 20)

$Proof = [ordered]@{
  step = "STEP_01K2_PARSE_SAFE_EXACT_LOCKED_REFERENCE_LAYOUT"
  status = "COMPLETE"
  created_at = $Now
  repo = $Repo
  safety_backup = $BackupRoot
  locked_reference_asset_sha256 = $ActualImageSha
  expected_reference_asset_sha256 = $ExpectedImageSha
  changed_files = @(
    [ordered]@{ path = $HudRel; sha256 = (Sha256File $LiveHud) },
    [ordered]@{ path = $CssRel; sha256 = (Sha256File $LiveCss) },
    [ordered]@{ path = $AssetRel; sha256 = (Sha256File $LiveAsset) }
  )
  proof = "Exact reference image installed as cockpit background with live API/voice overlays."
  next_command_1 = "Stop the old Next server window with Ctrl+C"
  next_command_2 = "cd /d C:\Kingsmen\kingsmen-platform\apps\web && npm run dev -- -H 127.0.0.1 -p 3000"
  next_command_3 = "start msedge --app=http://127.0.0.1:3000/jarvis"
}
WriteNoBom $ProofPath ($Proof | ConvertTo-Json -Depth 30)

$Report = @(
  "# STEP 01K - Force Exact Locked Reference Layout",
  "",
  "Created: $Now",
  "",
  "Status: COMPLETE",
  "",
  "Safety backup:",
  "- $BackupRoot",
  "",
  "Changed files:",
  "- $HudRel",
  "- $CssRel",
  "- $AssetRel",
  "",
  "Locked reference SHA256:",
  "- $ActualImageSha",
  "",
  "Next exact commands:",
  "",
  "Server command:",
  "cd /d C:\Kingsmen\kingsmen-platform\apps\web && npm run dev -- -H 127.0.0.1 -p 3000",
  "",
  "Open command:",
  "C:\Kingsmen\OPEN_JARVIS_LOCKED.cmd",
  ""
)
WriteNoBom $ReportPath (($Report -join "`r`n") + "`r`n")

$Ledger = @(
  "",
  "## STEP 01K - Force Exact Locked Reference Layout",
  "",
  "Status: COMPLETE at $Now",
  "",
  "Safety backup:",
  "- $BackupRoot",
  "",
  "Changed files:",
  "- $HudRel",
  "- $CssRel",
  "- $AssetRel",
  "",
  "Proof:",
  "- $ProofPath",
  "- $ReportPath",
  ""
)
Add-Content -Path (Join-Path $DocsDir "JARVIS_BUILD_STEP_LEDGER.md") -Value $Ledger -Encoding UTF8

if ($PSCommandPath) {
  Copy-Item $PSCommandPath (Join-Path $ToolsDir "KINGSMEN_JARVIS_STEP_01K2_PARSE_SAFE_EXACT_LOCKED_REFERENCE_LAYOUT.ps1") -Force
}

$CmdPath = "C:\Kingsmen\JARVIS_STEP_01K2_PARSE_SAFE_EXACT_LOCKED_REFERENCE_LAYOUT.cmd"
$CmdLines = @(
  "@echo off",
  "title KINGSMEN JARVIS STEP 01K FORCE EXACT LOCKED REFERENCE",
  "powershell -ExecutionPolicy Bypass -NoExit -File ""C:\Kingsmen\kingsmen-platform\tools\jarvis\KINGSMEN_JARVIS_STEP_01K2_PARSE_SAFE_EXACT_LOCKED_REFERENCE_LAYOUT.ps1"""
)
[System.IO.File]::WriteAllLines($CmdPath, $CmdLines, [System.Text.Encoding]::ASCII)
Write-Host ("WROTE: " + $CmdPath) -ForegroundColor Green

$OpenCmd = "C:\Kingsmen\OPEN_JARVIS_LOCKED.cmd"
$OpenLines = @(
  "@echo off",
  "start msedge --app=http://127.0.0.1:3000/jarvis"
)
[System.IO.File]::WriteAllLines($OpenCmd, $OpenLines, [System.Text.Encoding]::ASCII)
Write-Host ("WROTE: " + $OpenCmd) -ForegroundColor Green

Write-Host ""
Write-Host "STEP 01K2 COMPLETE." -ForegroundColor Green
Write-Host "Changed files:" -ForegroundColor Cyan
Write-Host $HudRel
Write-Host $CssRel
Write-Host $AssetRel
Write-Host ""
Write-Host "Proof:" -ForegroundColor Cyan
Write-Host $ProofPath
Write-Host $ReportPath
Write-Host ""
Write-Host "Now restart the Next server window, then run:" -ForegroundColor Yellow
Write-Host "C:\Kingsmen\OPEN_JARVIS_LOCKED.cmd" -ForegroundColor Yellow
